package it.carmine.streamplayer;
public final class CbSeriesNavigationCheck {
 public static void main(String[] args){String page="https://cb01.example/serie/show";CbSeriesNavigation.Result seasons=CbSeriesNavigation.parse("<a href='/serie/show/stagione-1'>Stagione 1</a><a href='/serie/show/stagione-2'>Season 2</a><a href='https://adsco.re/x'>Stagione 9</a>",page);if(seasons.seasons.size()!=2||seasons.seasons.get(0).season!=1||seasons.seasons.get(1).season!=2)throw new AssertionError("Season parsing failed");CbSeriesNavigation.Result episodes=CbSeriesNavigation.parse("<a href='/watch/1'>S1E1 Pilota</a><button data-url='/watch/2'>1x02 Secondo episodio</button><option value='/watch/3'>Episodio 3</option><a href='/trailer'>Episodio 4 trailer</a>",page);if(episodes.episodes.size()!=3)throw new AssertionError("Episode parsing failed: "+episodes.episodes.size());if(episodes.episodes.get(0).episode!=1||episodes.episodes.get(1).episode!=2||episodes.episodes.get(2).episode!=3)throw new AssertionError("Episode order failed");System.out.println("CB01 series navigation: 8 assertions passed");}
}
